# Search simple quotient/remainder coordinate formulas modulo3 with color mapping consistency
forms={}
for p in range(1,6):
 for q in range(1,6):
  forms[f'r//{p}+c//{q}']=lambda r,c,p=p,q=q:r//p+c//q
  forms[f'r%{p}+c%{q}']=lambda r,c,p=p,q=q:r%p+c%q
  forms[f'r//{p}+c']=lambda r,c,p=p:r//p+c
  forms[f'r+c//{q}']=lambda r,c,q=q:r+c//q
  forms[f'r//{p}*c//{q}']=lambda r,c,p=p,q=q:(r//p)*(c//q)
